'use client';
import {useEffect,useRef,useState} from 'react';
import {hotelClient,hotelRpc,usd} from '@/lib/pilot';
import {prepareInvoiceCredit,readInvoiceCreditReceipt,loadPendingCredit,savePendingCredit,clearPendingCredit} from '@/lib/invoice-credit-issue';
import {readInvoiceCreditOptions} from '@/lib/invoice-credit-options';
type Props={tenant:string;property:string;invoice:string;actor:string;disabled:boolean;options:unknown};
export function InvoiceCreditAction(props:Props){return <Action key={[props.tenant,props.property,props.invoice,props.actor].join(':')} {...props}/>;}
function Action({disabled,options,...scope}:Props){
 const [pending,setPending]=useState<ReturnType<typeof prepareInvoiceCredit>|null>(null),[busy,setBusy]=useState(false),[error,setError]=useState(''),[message,setMessage]=useState(''),[confirmed,setConfirmed]=useState(false),[cancelConfirmed,setCancelConfirmed]=useState(false),[consumedOptions,setConsumedOptions]=useState<unknown>(null);const alive=useRef(false),lock=useRef(false);
 useEffect(()=>{alive.current=true;try{setPending(loadPendingCredit(sessionStorage,scope));}catch(cause){setError(cause instanceof Error?cause.message:'Cannot read pending credit.');}return()=>{alive.current=false;};},[scope.tenant,scope.property,scope.invoice,scope.actor]);
 let lines:ReturnType<typeof readInvoiceCreditOptions>['lines']=[];try{if(options)lines=readInvoiceCreditOptions(options,scope).lines.filter(p=>p.available_minor!=='0');}catch{}
 function review(form:FormData){try{if(loadPendingCredit(sessionStorage,scope))throw Error('Resolve the saved credit first.');const selected=lines.flatMap(line=>{const value=String(form.get('line-'+line.line_number)||'').trim();if(!value)return [];if(!/^(0|[1-9][0-9]{0,9})(\.[0-9]{1,2})?$/.test(value))throw Error('Enter credit amounts with at most two decimal places.');const [whole,fraction='']=value.split('.');const amount=BigInt(whole)*BigInt(100)+BigInt(fraction.padEnd(2,'0'));return amount===BigInt(0)?[]:[{line_number:line.line_number,amount_minor:amount.toString()}];});const request=prepareInvoiceCredit(scope,crypto.randomUUID(),options,{lines:selected,effective_on:String(form.get('date')),reason:String(form.get('reason'))});setPending(savePendingCredit(sessionStorage,scope,request));setConfirmed(false);setCancelConfirmed(false);setError('');setMessage('');}catch(cause){setError(cause instanceof Error?cause.message:'Review credit details.');}}
 async function run(status:boolean,cancel=false){if(lock.current||disabled||!pending||(cancel?!cancelConfirmed:(!status&&!confirmed)))return;lock.current=true;setBusy(true);setError('');setMessage('');try{
  const user=await hotelClient().auth.getUser();if(user.error||user.data.user?.id!==scope.actor)throw Error('Sign-in changed. Reopen this invoice.');if(!alive.current)return;
  const result=await hotelRpc<unknown>(cancel?'cancel_invoice_credit_request':status?'invoice_credit_status':'issue_invoice_credit',cancel?{p_tenant:scope.tenant,p_property:scope.property,p_request:pending.args.p_request,p_confirmed:true}:status?{p_tenant:scope.tenant,p_property:scope.property,p_request:pending.args.p_request}:pending.args);
  const again=await hotelClient().auth.getUser();if(again.error||again.data.user?.id!==scope.actor)throw Error('Sign-in changed. Recover after signing in.');if(!alive.current)return;

  if(cancel){const r=result as Record<string,unknown>;if(!r||r.schema_version!==1||r.tenant_id!==scope.tenant||r.property_id!==scope.property||r.actor_id!==scope.actor||r.request_id!==pending.args.p_request||r.cancelled!==true||typeof r.replayed!=='boolean')throw Error('Cancellation receipt does not match this credit.');clearPendingCredit(sessionStorage,scope,pending.args.p_request);setPending(null);setConfirmed(false);setCancelConfirmed(false);setConsumedOptions(options);setMessage('Unrecorded credit cancelled. Refresh history before preparing another credit.');return;}
  let receipt=result;if(status){const r=result as Record<string,unknown>;if(!r||r.schema_version!==1||r.tenant_id!==scope.tenant||r.property_id!==scope.property||r.actor_id!==scope.actor||r.request_id!==pending.args.p_request||typeof r.found!=='boolean')throw Error('Credit recovery scope changed.');if(!r.found){if(r.result!==null)throw Error('Invalid credit recovery response.');setMessage('No credit recorded yet. Confirm and retry the saved request.');return;}receipt=r.result;}
  readInvoiceCreditReceipt(receipt,pending);clearPendingCredit(sessionStorage,scope,pending.args.p_request);setPending(null);setConfirmed(false);setConsumedOptions(options);setMessage('Credit issued. Refresh invoice balances and credit history.');
 }catch(cause){if(alive.current)setError(cause instanceof Error?cause.message:'Credit interrupted. Check saved result.');}finally{lock.current=false;if(alive.current)setBusy(false);}}
 return <section className="pilot-settings"><h4>Issue credit note</h4><p>A credit note reduces the invoice balance. It does not refund a payment or change the guest folio.</p>{!pending&&lines.length>0&&options!==consumedOptions&&<form onSubmit={e=>{e.preventDefault();review(new FormData(e.currentTarget));}}><fieldset disabled={disabled||busy}>{lines.map(line=><label className="field" key={line.line_number}>Credit for {line.description} (USD)<input name={'line-'+line.line_number} inputMode="decimal" placeholder="0.00"/></label>)}<label className="field">Credit date<input name="date" type="date" required/></label><label className="field">Credit reason<input name="reason" minLength={4} maxLength={500} required/></label><button>Review credit</button></fieldset></form>}{pending&&<><p>Saved credit: {usd(Number(pending.amount_minor))}  /  {pending.args.p_effective_on}</p><ul>{pending.args.p_lines.map(line=><li key={line.line_number}>Invoice line {line.line_number}: {usd(Number(line.amount_minor))}</li>)}</ul><p>{pending.args.p_reason}</p><label><input type="checkbox" checked={confirmed} disabled={busy||disabled} onChange={e=>setConfirmed(e.target.checked)}/>I confirm this credit note</label><button disabled={busy||disabled||!confirmed} onClick={()=>void run(false)}>Issue credit / retry</button><button disabled={busy||disabled} onClick={()=>void run(true)}>Check credit result</button><label><input type="checkbox" checked={cancelConfirmed} disabled={busy||disabled} onChange={e=>setCancelConfirmed(e.target.checked)}/>Cancel this request only if no credit was recorded</label><button disabled={busy||disabled||!cancelConfirmed} onClick={()=>void run(false,true)}>Cancel unrecorded credit</button></>}{error&&<p role="alert">{error}</p>}{message&&<p role="status">{message}</p>}</section>;
}
